<script setup lang="ts">
import { computed,reactive,ref,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElMessageBox } from 'element-plus';import { ElMessage } from '@/app/messages';import { addQuestion,adminDetail,newQuestionVersion,previewQuestion,publishQuestion,updateQuestion } from '@/api/question';import { readableError } from '@/api/errors';import type { AdminQuestion,ProblemFormValue,ValueType } from '@/api/types';import SafeMarkdown from '@/components/SafeMarkdown.vue'
const route=useRoute(),router=useRouter();const id=computed(()=>typeof route.params.problemId==='string'?route.params.problemId:null);const loading=ref(Boolean(id.value)),busy=ref(false),active=ref('basic'),meta=reactive({rowVersion:0,isPublished:false,problemVersion:1});const form=reactive<ProblemFormValue>({title:'',content:'',tags:[],answer:'',judgeCase:[{input:'',output:'',isHidden:true}],judgeConfig:{timeLimit:2000,memoryLimit:262144,outputLimitBytes:1048576},problemSpec:null});const preview=ref<Array<{language:string;fileName:string;code:string}>>([]);const types:ValueType[]=['int','long','double','boolean','string','int[]','long[]','double[]','boolean[]','string[]','int[][]','list<int>','list_node<int>','tree_node<int>']
function hydrate(q:AdminQuestion){form.title=q.title;form.content=q.content;form.tags=[...q.tags];form.answer=q.answer??'';form.judgeCase=q.judgeCase.map(v=>({...v}));form.judgeConfig={...q.judgeConfig};form.problemSpec=q.problemSpec?structuredClone(q.problemSpec):null;meta.rowVersion=q.rowVersion;meta.isPublished=q.isPublished;meta.problemVersion=q.problemVersion}
async function load(){if(!id.value)return;loading.value=true;try{hydrate(await adminDetail(id.value))}catch(e){ElMessage.error({ message: readableError(e) })}finally{loading.value=false}}watch(id,load,{immediate:true})
function setMode(mode:'ACM'|'FUNCTION'){if(mode==='ACM'){form.problemSpec=null;return}form.problemSpec={mode:'function',className:'Solution',methodName:'solve',parameters:[{name:'value',type:'int'}],returnType:'int',resultSource:'return',comparator:{type:'EXACT'},harnessVersion:1}}
function addParam(){if(form.problemSpec&&form.problemSpec.parameters.length<10)form.problemSpec.parameters.push({name:`arg${form.problemSpec.parameters.length}`,type:'int'})}function removeParam(i:number){form.problemSpec?.parameters.splice(i,1)}function addCase(){if(form.judgeCase.length<100)form.judgeCase.push({input:'',output:'',isHidden:true})}
function validate(){if(!form.title.trim()||form.title.length>80)return '标题长度应为 1–80';if(!form.content.trim()||form.content.length>8192)return '题面内容长度应为 1–8192';if(form.judgeCase.length===0)return '至少需要一个测试用例';if(form.judgeCase.some(c=>!c.input.trim()||!c.output.trim()))return '测试用例输入和输出不能为空';if(form.problemSpec&&(!form.problemSpec.methodName||form.problemSpec.parameters.length===0))return '函数模式需要方法名和至少一个参数';return ''}
async function save(){const message=validate();if(message){ElMessage.error({ message: message });return null}busy.value=true;try{if(!id.value){const created=await addQuestion(structuredClone(form));ElMessage.success({ message: '草稿已创建' });await router.replace(`/admin/problems/${created}/edit`);return created}await updateQuestion(id.value,meta.rowVersion,structuredClone(form));meta.rowVersion++;ElMessage.success({ message: '草稿已保存' });return id.value}catch(e){ElMessage.error({ message: readableError(e) });return null}finally{busy.value=false}}
async function runPreview(){const message=validate();if(message){ElMessage.error({ message: message });return}busy.value=true;try{const result=await previewQuestion(structuredClone(form));preview.value=result.templates;active.value='preview';ElMessage.success({ message: '规格校验通过' })}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
async function publish(){if(!id.value){ElMessage.warning({ message: '请先保存草稿' });return}await ElMessageBox.confirm('发布后当前版本的评测字段将变为只读。','确认发布',{type:'warning'});busy.value=true;try{const result=await publishQuestion(id.value,meta.rowVersion);meta.isPublished=true;meta.rowVersion=result.rowVersion;meta.problemVersion=result.problemVersion;ElMessage.success({ message: '题目已发布' })}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
async function makeVersion(){if(!id.value)return;try{const next=await newQuestionVersion(id.value,meta.rowVersion);await router.push(`/admin/problems/${next}/edit`)}catch(e){ElMessage.error({ message: readableError(e) })}}
</script>
<template><div class="page edit-page"><div class="page-head"><div><p class="crumb"><RouterLink to="/admin/problems">题目管理</RouterLink> / {{id?'编辑':'新建'}}</p><h1 class="page-title">{{id?form.title||'编辑题目':'新建题目'}}</h1><p v-if="id" class="page-lead">版本 {{meta.problemVersion}} · {{meta.isPublished?'已发布，只读':'草稿'}}</p></div><div class="actions"><el-button v-if="meta.isPublished" @click="makeVersion">创建新版本</el-button><template v-else><el-button :loading="busy" @click="runPreview">预览与校验</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button><el-button type="success" :loading="busy" :disabled="!id" @click="publish">发布</el-button></template></div></div><el-skeleton v-if="loading" :rows="10" animated/><section v-else class="surface form-shell"><el-alert v-if="meta.isPublished" title="已发布版本的题面与评测配置不可原地修改。请创建新版本后编辑。" type="info" :closable="false"/><el-tabs v-model="active"><el-tab-pane label="基础信息" name="basic"><el-form label-position="top" :disabled="meta.isPublished"><el-form-item label="标题"><el-input v-model="form.title" maxlength="80" show-word-limit/></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple filterable allow-create default-first-option placeholder="输入标签后回车"/></el-form-item><el-form-item label="题面 Markdown"><el-input v-model="form.content" type="textarea" :rows="14" maxlength="8192" show-word-limit/></el-form-item><el-form-item label="参考答案（仅管理员可见）"><el-input v-model="form.answer" type="textarea" :rows="5"/></el-form-item></el-form></el-tab-pane><el-tab-pane label="模式与签名" name="signature"><div class="section" :class="{readonly:meta.isPublished}"><el-radio-group :model-value="form.problemSpec?'FUNCTION':'ACM'" :disabled="meta.isPublished" @change="(v:string|number|boolean)=>setMode(v as 'ACM'|'FUNCTION')"><el-radio-button value="ACM">完整程序模式</el-radio-button><el-radio-button value="FUNCTION">函数模式</el-radio-button></el-radio-group><template v-if="form.problemSpec"><div class="signature-grid"><el-input v-model="form.problemSpec.methodName" :disabled="meta.isPublished"><template #prepend>Solution.</template></el-input><el-select v-model="form.problemSpec.returnType" :disabled="meta.isPublished"><el-option v-for="t in [...types,'void']" :key="t" :value="t"/></el-select><el-select v-model="form.problemSpec.resultSource" :disabled="meta.isPublished"><el-option label="方法返回值" value="return"/><el-option v-for="(_,i) in form.problemSpec.parameters" :key="i" :label="`参数 ${i}`" :value="`parameter:${i}`"/></el-select></div><h3>参数（最多 10 项）</h3><div v-for="(param,i) in form.problemSpec.parameters" :key="i" class="param"><el-input v-model="param.name" :disabled="meta.isPublished"/><el-select v-model="param.type" :disabled="meta.isPublished"><el-option v-for="t in types" :key="t" :value="t"/></el-select><el-button :disabled="meta.isPublished||form.problemSpec.parameters.length===1" @click="removeParam(i)">删除</el-button></div><el-button :disabled="meta.isPublished||form.problemSpec.parameters.length>=10" @click="addParam">添加参数</el-button></template><p v-else class="muted">参赛者提交包含标准输入输出入口的完整程序。</p></div></el-tab-pane><el-tab-pane label="用例" name="cases"><div v-for="(test,i) in form.judgeCase" :key="i" class="case"><div class="case-head"><strong>用例 {{i+1}}</strong><el-switch v-model="test.isHidden" :disabled="meta.isPublished" active-text="隐藏" inactive-text="公开样例"/><el-button link type="danger" :disabled="meta.isPublished||form.judgeCase.length===1" @click="form.judgeCase.splice(i,1)">删除</el-button></div><div class="case-grid"><el-input v-model="test.input" type="textarea" :rows="5" placeholder="输入" :disabled="meta.isPublished"/><el-input v-model="test.output" type="textarea" :rows="5" placeholder="期望输出" :disabled="meta.isPublished"/></div></div><el-button :disabled="meta.isPublished||form.judgeCase.length>=100" @click="addCase">添加用例</el-button></el-tab-pane><el-tab-pane label="资源" name="resources"><el-form class="limits" label-position="top" :disabled="meta.isPublished"><el-form-item label="时间限制（ms）"><el-input-number v-model="form.judgeConfig.timeLimit" :min="1" :max="30000"/></el-form-item><el-form-item label="内存限制（MiB）"><el-input-number :model-value="form.judgeConfig.memoryLimit/1024" :min="1" :max="1024" @update:model-value="(v:number|undefined)=>form.judgeConfig.memoryLimit=Number(v)*1024"/></el-form-item><el-form-item label="输出限制（KiB）"><el-input-number :model-value="form.judgeConfig.outputLimitBytes/1024" :min="1" :max="65536" @update:model-value="(v:number|undefined)=>form.judgeConfig.outputLimitBytes=Number(v)*1024"/></el-form-item></el-form></el-tab-pane><el-tab-pane label="预览" name="preview"><div class="preview"><SafeMarkdown :source="form.content||'*暂无题面内容*'"/><div v-if="preview.length"><h2>生成的语言模板</h2><el-tabs><el-tab-pane v-for="item in preview" :key="item.language" :label="item.language"><p class="mono">{{item.fileName}}</p><pre class="mono">{{item.code}}</pre></el-tab-pane></el-tabs></div><el-empty v-else description="点击“预览与校验”生成实际语言模板"/></div></el-tab-pane></el-tabs></section></div></template>
<style scoped>.edit-page{max-width:1100px}.crumb{margin:0 0 8px;color:var(--oj-text-muted)}.actions{display:flex;gap:8px;flex-wrap:wrap}.form-shell{padding:18px 24px 30px}.section{padding:10px 2px}.signature-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:12px;margin:22px 0}.param{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;margin-bottom:10px}.case{border:1px solid var(--oj-border);border-radius:8px;padding:14px;margin-bottom:14px}.case-head{display:flex;align-items:center;gap:18px;margin-bottom:12px}.case-head strong{margin-right:auto}.case-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.limits{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;max-width:760px}.preview{padding:8px 4px}.preview pre{background:#111827;color:#e5e7eb;padding:16px;border-radius:7px;overflow:auto}@media(max-width:767px){.signature-grid,.case-grid,.limits{grid-template-columns:1fr}.param{grid-template-columns:1fr}.actions{width:100%}}</style>
